/* silk/code_signs.c */

#define oe_silk_enc_map(a)                  ( oe_silk_RSHIFT( (a), 15 ) + 1 )

#define oe_silk_dec_map(a)                  ( oe_silk_LSHIFT( (a),  1 ) - 1 )

static void oe_silk_encode_signs(
    oe_ec_enc                      *psRangeEnc,
    const oe_opus_int8             pulses[],
    oe_opus_int                    length,
    const oe_opus_int              signalType,
    const oe_opus_int              quantOffsetType,
    const oe_opus_int              sum_pulses[ oe_MAX_NB_SHELL_BLOCKS ]
)
{
    oe_opus_int         i, j, p;
    oe_opus_uint8       icdf[ 2 ];
    const oe_opus_int8  *q_ptr;
    const oe_opus_uint8 *icdf_ptr;

    icdf[ 1 ] = 0;
    q_ptr = pulses;
    i = oe_silk_SMULBB( 7, oe_silk_ADD_LSHIFT( quantOffsetType, signalType, 1 ) );
    icdf_ptr = &oe_silk_sign_iCDF[ i ];
    length = oe_silk_RSHIFT( length + oe_SHELL_CODEC_FRAME_LENGTH/2, oe_LOG2_SHELL_CODEC_FRAME_LENGTH );
    for( i = 0; i < length; i++ ) {
        p = sum_pulses[ i ];
        if( p > 0 ) {
            icdf[ 0 ] = icdf_ptr[ oe_silk_min( p & 0x1F, 6 ) ];
            for( j = 0; j < oe_SHELL_CODEC_FRAME_LENGTH; j++ ) {
                if( q_ptr[ j ] != 0 ) {
                    oe_ec_enc_icdf( psRangeEnc, oe_silk_enc_map( q_ptr[ j ]), icdf, 8 );
                }
            }
        }
        q_ptr += oe_SHELL_CODEC_FRAME_LENGTH;
    }
}

