static oe_opus_int oe_silk_control_SNR(
    oe_silk_encoder_state          *psEncC,
    oe_opus_int32                  TargetRate_bps
)
{
    int id;
    int bound;
    const unsigned char *snr_table;

    psEncC->TargetRate_bps = TargetRate_bps;
    if( psEncC->nb_subfr == 2 ) {
        TargetRate_bps -= 2000 + psEncC->fs_kHz/16;
    }
    if( psEncC->fs_kHz == 8 ) {
        bound = sizeof(oe_silk_TargetRate_NB_21);
        snr_table = oe_silk_TargetRate_NB_21;
    } else if( psEncC->fs_kHz == 12 ) {
        bound = sizeof(oe_silk_TargetRate_MB_21);
        snr_table = oe_silk_TargetRate_MB_21;
    } else {
        bound = sizeof(oe_silk_TargetRate_WB_21);
        snr_table = oe_silk_TargetRate_WB_21;
    }
    id = (TargetRate_bps+200)/400;
    id = oe_silk_min(id - 10, bound-1);
    if( id <= 0 ) {
        psEncC->SNR_dB_Q7 = 0;
    } else {
        psEncC->SNR_dB_Q7 = snr_table[id]*21;
    }
    return oe_SILK_NO_ERROR;
}

/* silk/init_encoder.c */

static oe_opus_int oe_silk_init_encoder(
    oe_silk_encoder_state_Fxx          *psEnc,
    int                              arch
)
{
    oe_opus_int ret = 0;

    oe_silk_memset( psEnc, 0, sizeof( oe_silk_encoder_state_Fxx ) );

    psEnc->sCmn.arch = arch;

    psEnc->sCmn.variable_HP_smth1_Q15 = oe_silk_LSHIFT( oe_silk_lin2log( oe_SILK_FIX_CONST( oe_VARIABLE_HP_MIN_CUTOFF_HZ, 16 ) ) - ( 16 << 7 ), 8 );
    psEnc->sCmn.variable_HP_smth2_Q15 = psEnc->sCmn.variable_HP_smth1_Q15;

    psEnc->sCmn.first_frame_after_reset = 1;

    ret += oe_silk_VAD_Init( &psEnc->sCmn.sVAD );

    return  ret;
}

