static oe_opus_int32 oe_opus_packet_extensions_count(const unsigned char *data,
 oe_opus_int32 len, int nb_frames);
static oe_opus_int32 oe_opus_packet_pad_impl(unsigned char *data, oe_opus_int32 len, oe_opus_int32 new_len, int pad, const oe_opus_extension_data  *extensions, int nb_extensions);

#endif

static int oe_encode_size(int size, unsigned char *data)
{
   if (size < 252)
   {
      data[0] = size;
      return 1;
   } else {
      data[0] = 252+(size&0x3);
      data[1] = (size-(int)data[0])>>2;
      return 2;
   }
}
static int oe_parse_size(const unsigned char *data, oe_opus_int32 len, oe_opus_int16 *size)
{
   if (len<1)
   {
      *size = -1;
      return -1;
   } else if (data[0]<252)
   {
      *size = data[0];
      return 1;
   } else if (len<2)
   {
      *size = -1;
      return -1;
   } else {
      *size = 4*data[1] + data[0];
      return 2;
   }
}
static int oe_opus_packet_get_samples_per_frame(const unsigned char *data,
      oe_opus_int32 Fs)
{
   int audiosize;
   if (data[0]&0x80)
   {
      audiosize = ((data[0]>>3)&0x3);
      audiosize = (Fs<<audiosize)/400;
   } else if ((data[0]&0x60) == 0x60)
   {
      audiosize = (data[0]&0x08) ? Fs/50 : Fs/100;
   } else {
      audiosize = ((data[0]>>3)&0x3);
      if (audiosize == 3)
         audiosize = Fs*60/1000;
      else
         audiosize = (Fs<<audiosize)/100;
   }
   return audiosize;
}
static int oe_opus_packet_parse_impl(const unsigned char *data, oe_opus_int32 len,
      int self_delimited, unsigned char *out_toc,
      const unsigned char *frames[48], oe_opus_int16 size[48],
      int *payload_offset, oe_opus_int32 *packet_offset,
      const unsigned char **padding, oe_opus_int32 *padding_len)
{
   int i, bytes;
   int count;
   int cbr;
   unsigned char ch, toc;
   int framesize;
   oe_opus_int32 last_size;
   oe_opus_int32 pad = 0;
   const unsigned char *data0 = data;

   if (padding != NULL)
   {
      *padding = NULL;
      *padding_len = 0;
   }

   if (size==NULL || len<0)
      return oe_OPUS_BAD_ARG;
   if (len==0)
      return oe_OPUS_INVALID_PACKET;

   framesize = oe_opus_packet_get_samples_per_frame(data, 48000);

   cbr = 0;
   toc = *data++;
   len--;
   last_size = len;
   switch (toc&0x3)
   {

   case 0:
      count=1;
      break;

   case 1:
      count=2;
      cbr = 1;
      if (!self_delimited)
      {
         if (len&0x1)
            return oe_OPUS_INVALID_PACKET;
         last_size = len/2;

         size[0] = (oe_opus_int16)last_size;
      }
      break;

   case 2:
      count = 2;
      bytes = oe_parse_size(data, len, size);
      len -= bytes;
      if (size[0]<0 || size[0] > len)
         return oe_OPUS_INVALID_PACKET;
      data += bytes;
      last_size = len-size[0];
      break;

   default:
      if (len<1)
         return oe_OPUS_INVALID_PACKET;

      ch = *data++;
      count = ch&0x3F;
      if (count <= 0 || framesize*(oe_opus_int32)count > 5760)
         return oe_OPUS_INVALID_PACKET;
      len--;

      if (ch&0x40)
      {
         int p;
         do {
            int tmp;
            if (len<=0)
               return oe_OPUS_INVALID_PACKET;
            p = *data++;
            len--;
            tmp = p==255 ? 254: p;
            len -= tmp;
            pad += tmp;
         } while (p==255);
      }
      if (len<0)
         return oe_OPUS_INVALID_PACKET;

      cbr = !(ch&0x80);
      if (!cbr)
      {

         last_size = len;
         for (i=0;i<count-1;i++)
         {
            bytes = oe_parse_size(data, len, size+i);
            len -= bytes;
            if (size[i]<0 || size[i] > len)
               return oe_OPUS_INVALID_PACKET;
            data += bytes;
            last_size -= bytes+size[i];
         }
         if (last_size<0)
            return oe_OPUS_INVALID_PACKET;
      } else if (!self_delimited)
      {

         last_size = len/count;
         if (last_size*count!=len)
            return oe_OPUS_INVALID_PACKET;
         for (i=0;i<count-1;i++)
            size[i] = (oe_opus_int16)last_size;
      }
      break;
   }

   if (self_delimited)
   {
      bytes = oe_parse_size(data, len, size+count-1);
      len -= bytes;
      if (size[count-1]<0 || size[count-1] > len)
         return oe_OPUS_INVALID_PACKET;
      data += bytes;

      if (cbr)
      {
         if (size[count-1]*count > len)
            return oe_OPUS_INVALID_PACKET;
         for (i=0;i<count-1;i++)
            size[i] = size[count-1];
      } else if (bytes+size[count-1] > last_size)
         return oe_OPUS_INVALID_PACKET;
   } else
   {

      if (last_size > 1275)
         return oe_OPUS_INVALID_PACKET;
      size[count-1] = (oe_opus_int16)last_size;
   }

   if (payload_offset)
      *payload_offset = (int)(data-data0);

   for (i=0;i<count;i++)
   {
      if (frames)
         frames[i] = data;
      data += size[i];
   }

   if (padding != NULL)
   {
      *padding = data;
      *padding_len = pad;
   }
   if (packet_offset)
      *packet_offset = pad+(oe_opus_int32)(data-data0);

   if (out_toc)
      *out_toc = toc;

   return count;
}

